body.t-aurora .bg-fx { overflow: hidden; }
body.t-aurora .bg-fx::before, body.t-aurora .bg-fx::after {
  content: ""; position: absolute; inset: -25% -40% 40% -40%;
  background: linear-gradient(100deg, transparent 15%, rgba(74,222,128,.16) 35%, rgba(34,211,238,.13) 52%, rgba(167,139,250,.16) 68%, transparent 88%);
  filter: blur(46px);
  animation: aurora-flow 13s ease-in-out infinite alternate;
}
body.t-aurora .bg-fx::after { animation-duration: 19s; animation-delay: -6s; opacity: .6; transform: scaleY(-1); }
@keyframes aurora-flow {
  0% { transform: translateX(-6%) skewX(-8deg); opacity: .55; }
  50% { opacity: .95; }
  100% { transform: translateX(6%) skewX(6deg); opacity: .6; }
}
@media (prefers-reduced-motion: reduce) { body.t-aurora .bg-fx::before, body.t-aurora .bg-fx::after { animation: none; } }
body.t-aurora .card, body.t-aurora .post, body.t-aurora .fact, body.t-aurora .contact-card,
body.t-aurora .hero-badge, body.t-aurora .tag, body.t-aurora .section-tag {
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
}
